teljes kódot kijavítva vissza küldöd. minden egyes karaktert leírsz, nem rövidítesz. minden hibát kijavítasz. egy fájl marad. ne írj semmi mást csak a teljes kódot es kommentek nem lehetnek benne! soha semmi egyszerusitett mock placeholder dummy szimulalt fake szart nem engedelyezek es teljes fájl roviditetlen production ready kód  egy kód mezőbe írjad a teljes kódot es legyen 100% osan hiba mentes! 


<!-- Canvas elem a HTML body-ban -->
<canvas id="tubes-canvas"></canvas>

<!-- CSS stílusok -->
<style>
#tubes-canvas {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
  opacity: 0.8;
  pointer-events: none;
  display: none;
}
</style>

<!-- JavaScript a rózsaszín csövek animációjához -->
<script type="module">
import TubesCursor from "";

let cursorApp = null;
let animationTimeout = null;
const tubesCanvas = document.getElementById('tubes-canvas');

function startTubesAnimation() {
  if (!cursorApp) {
    cursorApp = TubesCursor(tubesCanvas, {
      tubes: {
        colors: ["#ff1493", "#ff69b4", "#ffffff"],
        lights: {
          intensity: 20,
          colors: ["#ff1493", "#ffffff", "#ffb6c1"]
        }
      },
      speed: 0.5
    });
  }
  tubesCanvas.style.display = 'block';
  clearTimeout(animationTimeout);
  animationTimeout = setTimeout(stopTubesAnimation, 8000);
}

function stopTubesAnimation() {
  tubesCanvas.style.display = 'none';
}

function randomColors(count) {
  const colors = [];
  for(let i=0; i<count; i++) {
    const hue = 300 + Math.random() * 40;
    colors.push(`hsl(${hue}, 100%, 60%)`);
  }
  return colors;
}

// Aktiválás érintésre
document.body.addEventListener('touchstart', () => {
  startTubesAnimation();
});

// Aktiválás kattintásra
document.body.addEventListener('click', (e) => {
  if (e.target.tagName !== 'BUTTON' && e.target.tagName !== 'INPUT' && !e.target.closest('.message-bubble') && !e.target.closest('.floating-menu')) {
    startTubesAnimation();
    if (cursorApp) {
      cursorApp.tubes.setColors(randomColors(3));
      cursorApp.tubes.setLightsColors(randomColors(4));
    }
  }
});
</script>

