<!doctype html>
<html lang="hu">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
  <meta name="source" content="[web:90] [web:7]">
  <title>Tubes Cursor</title>
  <style>
    html, body {
      width: 100%;
      height: 100%;
      margin: 0;
      padding: 0;
    }
    #tubes-canvas {
      position: fixed;
      inset: 0;
      width: 100%;
      height: 100%;
      z-index: 1;
      opacity: 0;
      visibility: hidden;
      pointer-events: none;
      display: block;
      transition: opacity 160ms linear, visibility 0s linear 160ms;
    }
  </style>
</head>
<body>
  <canvas id="tubes-canvas"></canvas>

  <script type="module">
    const TUBES_CURSOR_URL = "";

    const tubesCanvas = document.getElementById("tubes-canvas");
    let cursorApp = null;
    let stopTimeoutId = null;
    let resizeRafId = 0;
    let TubesCursorFactoryPromise = null;

    function clampNumber(value, min, max) {
      const n = Number(value);
      if (!Number.isFinite(n)) return min;
      return Math.min(max, Math.max(min, n));
    }

    function getDevicePixelRatio() {
      return clampNumber(window.devicePixelRatio || 1, 1, 3);
    }

    function syncCanvasSize() {
      const dpr = getDevicePixelRatio();
      const cssWidth = Math.max(1, Math.floor(window.innerWidth));
      const cssHeight = Math.max(1, Math.floor(window.innerHeight));
      const pixelWidth = Math.max(1, Math.floor(cssWidth * dpr));
      const pixelHeight = Math.max(1, Math.floor(cssHeight * dpr));
      if (tubesCanvas.width !== pixelWidth) tubesCanvas.width = pixelWidth;
      if (tubesCanvas.height !== pixelHeight) tubesCanvas.height = pixelHeight;
      if (tubesCanvas.style.width !== cssWidth + "px") tubesCanvas.style.width = cssWidth + "px";
      if (tubesCanvas.style.height !== cssHeight + "px") tubesCanvas.style.height = cssHeight + "px";
    }

    function scheduleResizeSync() {
      if (resizeRafId) return;
      resizeRafId = window.requestAnimationFrame(() => {
        resizeRafId = 0;
        syncCanvasSize();
      });
    }

    function showCanvas() {
      tubesCanvas.style.visibility = "visible";
      tubesCanvas.style.transitionDelay = "0s, 0s";
      tubesCanvas.style.opacity = "0.8";
    }

    function hideCanvas() {
      tubesCanvas.style.opacity = "0";
      tubesCanvas.style.transitionDelay = "0s, 160ms";
      tubesCanvas.style.visibility = "hidden";
    }

    function clearStopTimer() {
      if (stopTimeoutId !== null) {
        clearTimeout(stopTimeoutId);
        stopTimeoutId = null;
      }
    }

    function scheduleStop(delayMs) {
      clearStopTimer();
      stopTimeoutId = setTimeout(() => {
        stopTimeoutId = null;
        stopTubesAnimation();
      }, delayMs);
    }

    function randomColors(count) {
      const colors = [];
      const safeCount = Math.max(0, Math.floor(count));
      for (let i = 0; i < safeCount; i++) {
        const hue = 300 + Math.random() * 40;
        colors.push("hsl(" + hue.toFixed(3) + ", 100%, 60%)");
      }
      return colors;
    }

    function isBlockedTarget(target) {
      if (!(target instanceof Element)) return false;
      const tag = target.tagName;
      if (tag === "BUTTON" || tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT" || tag === "OPTION" || tag === "A" || tag === "LABEL") return true;
      if (target.isContentEditable) return true;
      if (target.closest(".message-bubble")) return true;
      if (target.closest(".floating-menu")) return true;
      return false;
    }

    function getTubesCursorFactory() {
      if (!TubesCursorFactoryPromise) {
        TubesCursorFactoryPromise = import(TUBES_CURSOR_URL).then((m) => {
          if (m && typeof m.default === "function") return m.default;
          if (typeof m === "function") return m;
          throw new Error("Invalid TubesCursor module export");
        });
      }
      return TubesCursorFactoryPromise;
    }

    async function ensureCursorApp() {
      if (cursorApp) return cursorApp;
      syncCanvasSize();
      const TubesCursor = await getTubesCursorFactory();
      cursorApp = TubesCursor(tubesCanvas, {
        tubes: {
          colors: ["#ff1493", "#ff69b4", "#ffffff"],
          lights: {
            intensity: 20,
            colors: ["#ff1493", "#ffffff", "#ffb6c1", "#ffd1e8"]
          }
        },
        speed: 0.5
      });
      return cursorApp;
    }

    function safeCall(fn, ...args) {
      try {
        if (typeof fn === "function") fn(...args);
      } catch (e) {
      }
    }

    async function startTubesAnimation(withRandomize) {
      try {
        const app = await ensureCursorApp();
        showCanvas();
        scheduleStop(8000);
        safeCall(app.resume);
        if (withRandomize && app && app.tubes) {
          safeCall(app.tubes.setColors, randomColors(3));
          safeCall(app.tubes.setLightsColors, randomColors(4));
        }
      } catch (e) {
      }
    }

    function stopTubesAnimation() {
      hideCanvas();
      if (cursorApp) {
        safeCall(cursorApp.pause);
      }
    }

    function destroyTubesAnimation() {
      clearStopTimer();
      hideCanvas();
      if (cursorApp) {
        safeCall(cursorApp.destroy);
        safeCall(cursorApp.dispose);
        cursorApp = null;
      }
      TubesCursorFactoryPromise = null;
    }

    function onActivateEvent(e) {
      const target = e && e.target ? e.target : null;
      if (isBlockedTarget(target)) return;
      startTubesAnimation(true);
    }

    syncCanvasSize();

    window.addEventListener("resize", scheduleResizeSync, { passive: true });
    window.addEventListener("orientationchange", scheduleResizeSync, { passive: true });

    document.addEventListener("visibilitychange", () => {
      if (document.hidden) {
        stopTubesAnimation();
        clearStopTimer();
      }
    }, { passive: true });

    window.addEventListener("pagehide", () => {
      destroyTubesAnimation();
    }, { passive: true });

    document.body.addEventListener("pointerdown", onActivateEvent, { passive: true });
    document.body.addEventListener("touchstart", onActivateEvent, { passive: true });
    document.body.addEventListener("click", onActivateEvent, { passive: true });
  </script>
</body>
</html>
